function sumOfLargestPrimes(s) {
  const isPrime = (candidate) => {
    if (candidate < 2) {
      return false;
    }
    for (let divisor = 2; divisor * divisor <= candidate; divisor++) {
      if (candidate % divisor === 0) {
        return false;
      }
    }
    return true;
  };
  const primes = new Set();
  for (let start = 0; start < s.length; start++) {
    let value = 0;
    for (let end = start; end < s.length; end++) {
      value = value * 10 + Number(s[end]);
      if (isPrime(value)) {
        primes.add(value);
      }
    }
  }
  const largest = [...primes].sort((a, b) => b - a).slice(0, 3);
  let total = 0;
  for (const prime of largest) {
    total += prime;
  }
  return total;
}

