function sumOfLargestPrimes(s) {
  // Parse every substring, sieve the small primes up to the square root of the biggest number,
  // and pull out the largest prime three times.
  const numbers = new Set();
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) numbers.add(parseInt(s.slice(i, j), 10));
  }
  const limit = Math.floor(Math.sqrt(Math.max(...numbers))) + 1;
  const composite = new Array(limit + 1).fill(false);
  const small = [];
  for (let p = 2; p <= limit; p++) {
    if (composite[p]) continue;
    small.push(p);
    for (let m = p * p; m <= limit; m += p) composite[m] = true;
  }
  const prime = v => v >= 2 && small.every(p => p * p > v || v % p !== 0);
  let rest = [...numbers].filter(prime), sum = 0;
  for (let k = 0; k < 3 && rest.length > 0; k++) {
    const top = Math.max(...rest);
    sum += top;
    rest = rest.filter(v => v !== top);
  }
  return sum;
}

