function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const length = size === 'large' ? 10 : int(1, 10);
  // Now and then the digits come from a pool of one to three digits, so repeats and leading zeros are common.
  const pool = rand() < 0.4 ? Array.from({ length: int(1, 3) }, () => String(int(0, 9))) : [...'0123456789'];
  let s = '';
  for (let i = 0; i < length; i++) s += pool[int(0, pool.length - 1)];
  return [s];
}
